#### Phase 1: Define Dependency Health Checks

**Step 1: Identify and Categorize Dependencies**

Create a dependency inventory for your service, categorizing each as critical or non-critical:

```yaml
# dependency-config.yml
dependencies:

  - name: sql-database
    type: database
    critical: true
    endpoint: "server=sql-prod;database=claims;user id=app"
    timeout: 2s
    cacheTTL: 10s

  - name: pricing-service
    type: http
    critical: true
    endpoint: "https://pricing-service/health"
    timeout: 3s
    cacheTTL: 15s
    circuitBreaker: true

  - name: redis-cache
    type: cache
    critical: false
    endpoint: "redis://cache-cluster:6379"
    timeout: 2s
    cacheTTL: 30s
```

**Critical Dependency Criteria**:
- Service cannot fulfill requests without it
- No reasonable fallback exists
- Failures should cause service to report Unhealthy

**Non-Critical Dependency Criteria**:
- Service can fulfill requests without it (possibly degraded)
- Fallback mechanism exists (e.g., database fallback when cache down)
- Failures should cause service to report Degraded

**Step 2: Implement Individual Dependency Health Checks**

ASP.NET implementation:

```csharp
// DependencyHealthChecks.cs
using Microsoft.Extensions.Diagnostics.HealthChecks;
using System.Data.SqlClient;

public class SqlDatabaseHealthCheck : IHealthCheck
{
    private readonly string _connectionString;
    private readonly ILogger<SqlDatabaseHealthCheck> _logger;

    public SqlDatabaseHealthCheck(string connectionString, ILogger<SqlDatabaseHealthCheck> logger)
    {
        _connectionString = connectionString;
        _logger = logger;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        try
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync(cancellationToken);

            // Check connection pool utilization
            var poolStats = GetConnectionPoolStats(connection);

            // Execute test query with timeout
            using var command = connection.CreateCommand();
            command.CommandText = "SELECT 1";
            command.CommandTimeout = 2; // 2 second timeout

            var stopwatch = Stopwatch.StartNew();
            await command.ExecuteScalarAsync(cancellationToken);
            stopwatch.Stop();

            var data = new Dictionary<string, object>
            {
                ["connectionPool"] = $"{poolStats.Active} / {poolStats.Max} ({poolStats.Percentage}%)",
                ["queryTime"] = $"{stopwatch.ElapsedMilliseconds}ms"
            };

            // Healthy if connection successful and query fast
            if (stopwatch.ElapsedMilliseconds < 500)
            {
                return HealthCheckResult.Healthy("Database connection healthy", data);
            }

            // Degraded if slow but functional
            return HealthCheckResult.Degraded($"Database responding slowly ({stopwatch.ElapsedMilliseconds}ms)", data: data);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Database health check failed");
            return HealthCheckResult.Unhealthy("Database connection failed", ex);
        }
    }
}

public class DownstreamServiceHealthCheck : IHealthCheck
{
    private readonly HttpClient _httpClient;
    private readonly string _serviceUrl;
    private readonly ICircuitBreakerPolicy _circuitBreaker;
    private readonly ILogger<DownstreamServiceHealthCheck> _logger;

    public DownstreamServiceHealthCheck(
        HttpClient httpClient,
        string serviceUrl,
        ICircuitBreakerPolicy circuitBreaker,
        ILogger<DownstreamServiceHealthCheck> logger)
    {
        _httpClient = httpClient;
        _serviceUrl = serviceUrl;
        _circuitBreaker = circuitBreaker;
        _logger = logger;
    }

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Check circuit breaker state first
            if (_circuitBreaker.State == CircuitState.Open)
            {
                return HealthCheckResult.Unhealthy(
                    $"Circuit breaker OPEN for {_serviceUrl}",
                    data: new Dictionary<string, object>
                    {
                        ["circuitBreaker"] = "OPEN",
                        ["lastFailure"] = _circuitBreaker.LastFailureTime
                    });
            }

            var stopwatch = Stopwatch.StartNew();

            // Execute health check through circuit breaker
            var response = await _circuitBreaker.ExecuteAsync(async () =>
            {
                var request = new HttpRequestMessage(HttpMethod.Get, $"{_serviceUrl}/health");
                request.Headers.Add("User-Agent", "HealthCheck/1.0");

                using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                cts.CancelAfter(TimeSpan.FromSeconds(3)); // 3 second timeout

                return await _httpClient.SendAsync(request, cts.Token);
            });

            stopwatch.Stop();

            var data = new Dictionary<string, object>
            {
                ["responseTime"] = $"{stopwatch.ElapsedMilliseconds}ms",
                ["statusCode"] = response.StatusCode,
                ["circuitBreaker"] = _circuitBreaker.State.ToString()
            };

            if (response.IsSuccessStatusCode)
            {
                return HealthCheckResult.Healthy($"Service {_serviceUrl} responding", data);
            }

            return HealthCheckResult.Unhealthy($"Service {_serviceUrl} returned {response.StatusCode}", data: data);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Downstream service health check failed for {ServiceUrl}", _serviceUrl);
            return HealthCheckResult.Unhealthy($"Service {_serviceUrl} health check failed", ex);
        }
    }
}
```

