#### Phase 2: Implement Health Check Aggregation

**Step 3: Create Health Aggregator Component**

```csharp
// HealthAggregator.cs
using Microsoft.Extensions.Diagnostics.HealthChecks;

public interface IHealthAggregator
{
    Task<AggregatedHealthReport> GetAggregatedHealthAsync(CancellationToken cancellationToken = default);
}

public class HealthAggregator : IHealthAggregator
{
    private readonly HealthCheckService _healthCheckService;
    private readonly IMemoryCache _cache;
    private readonly ILogger<HealthAggregator> _logger;

    public HealthAggregator(
        HealthCheckService healthCheckService,
        IMemoryCache cache,
        ILogger<HealthAggregator> logger)
    {
        _healthCheckService = healthCheckService;
        _cache = cache;
        _logger = logger;
    }

    public async Task<AggregatedHealthReport> GetAggregatedHealthAsync(
        CancellationToken cancellationToken = default)
    {
        var cacheKey = "aggregated-health";

        // Check cache first
        if (_cache.TryGetValue(cacheKey, out AggregatedHealthReport cachedReport))
        {
            _logger.LogDebug("Returning cached aggregated health report");
            return cachedReport;
        }

        var stopwatch = Stopwatch.StartNew();

        // Execute all health checks
        var healthReport = await _healthCheckService.CheckHealthAsync(cancellationToken);

        stopwatch.Stop();

        // Apply aggregation logic
        var aggregatedStatus = CalculateAggregatedStatus(healthReport);

        var report = new AggregatedHealthReport
        {
            Status = aggregatedStatus,
            Version = Assembly.GetEntryAssembly()?.GetName().Version?.ToString() ?? "unknown",
            ServiceId = Environment.GetEnvironmentVariable("SERVICE_ID") ?? Environment.MachineName,
            Timestamp = DateTimeOffset.UtcNow,
            Duration = stopwatch.ElapsedMilliseconds,
            Checks = ConvertToCheckResults(healthReport.Entries),
            Summary = CalculateSummary(healthReport.Entries)
        };

        // Cache for configured TTL (default 10 seconds)
        var cacheOptions = new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(10)
        };
        _cache.Set(cacheKey, report, cacheOptions);

        _logger.LogInformation(
            "Aggregated health check completed in {Duration}ms with status {Status}",
            stopwatch.ElapsedMilliseconds,
            aggregatedStatus);

        return report;
    }

    private HealthStatus CalculateAggregatedStatus(HealthReport healthReport)
    {
        // Rule 1: If self health check fails, return Unhealthy
        if (healthReport.Entries.TryGetValue("self", out var selfEntry)
            && selfEntry.Status == HealthStatus.Unhealthy)
        {
            return HealthStatus.Unhealthy;
        }

        // Rule 2: If any critical dependency is unhealthy, return Unhealthy
        var criticalDependencies = healthReport.Entries
            .Where(e => e.Key != "self" && IsCriticalDependency(e.Key))
            .ToList();

        if (criticalDependencies.Any(e => e.Value.Status == HealthStatus.Unhealthy))
        {
            return HealthStatus.Unhealthy;
        }

        // Rule 3: If any non-critical dependency is unhealthy, return Degraded
        var nonCriticalDependencies = healthReport.Entries
            .Where(e => e.Key != "self" && !IsCriticalDependency(e.Key))
            .ToList();

        if (nonCriticalDependencies.Any(e => e.Value.Status == HealthStatus.Unhealthy))
        {
            return HealthStatus.Degraded;
        }

        // Rule 4: If all checks pass, return Healthy
        return HealthStatus.Healthy;
    }

    private bool IsCriticalDependency(string dependencyName)
    {
        // Load from configuration
        var criticalDependencies = new[] { "database", "pricing-service", "payment-service" };
        return criticalDependencies.Contains(dependencyName);
    }

    private Dictionary<string, CheckResult> ConvertToCheckResults(
        IReadOnlyDictionary<string, HealthReportEntry> entries)
    {
        return entries.ToDictionary(
            e => e.Key,
            e => new CheckResult
            {
                Status = e.Value.Status.ToString().ToLowerInvariant(),
                Critical = IsCriticalDependency(e.Key),
                Duration = (long)e.Value.Duration.TotalMilliseconds,
                Details = e.Value.Data.ToDictionary(d => d.Key, d => d.Value),
                Error = e.Value.Exception?.Message
            });
    }

    private HealthSummary CalculateSummary(
        IReadOnlyDictionary<string, HealthReportEntry> entries)
    {
        return new HealthSummary
        {
            Total = entries.Count,
            Healthy = entries.Count(e => e.Value.Status == HealthStatus.Healthy),
            Degraded = entries.Count(e => e.Value.Status == HealthStatus.Degraded),
            Unhealthy = entries.Count(e => e.Value.Status == HealthStatus.Unhealthy),
            CriticalHealthy = entries.Count(e => IsCriticalDependency(e.Key) && e.Value.Status == HealthStatus.Healthy),
            CriticalUnhealthy = entries.Count(e => IsCriticalDependency(e.Key) && e.Value.Status == HealthStatus.Unhealthy)
        };
    }
}

public class AggregatedHealthReport
{
    public string Status { get; set; }
    public string Version { get; set; }
    public string ServiceId { get; set; }
    public DateTimeOffset Timestamp { get; set; }
    public long Duration { get; set; }
    public Dictionary<string, CheckResult> Checks { get; set; }
    public HealthSummary Summary { get; set; }
}

public class CheckResult
{
    public string Status { get; set; }
    public bool Critical { get; set; }
    public long Duration { get; set; }
    public Dictionary<string, object> Details { get; set; }
    public string Error { get; set; }
}

public class HealthSummary
{
    public int Total { get; set; }
    public int Healthy { get; set; }
    public int Degraded { get; set; }
    public int Unhealthy { get; set; }
    public int CriticalHealthy { get; set; }
    public int CriticalUnhealthy { get; set; }
}
```

**Step 4: Configure Health Checks in Startup**

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Add health checks
builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy("Service operational"))
    .AddCheck<SqlDatabaseHealthCheck>("database", tags: new[] { "critical", "database" })
    .AddCheck<DownstreamServiceHealthCheck>("pricing-service", tags: new[] { "critical", "service" })
    .AddCheck<DownstreamServiceHealthCheck>("payment-service", tags: new[] { "critical", "service" })
    .AddCheck<RedisHealthCheck>("redis-cache", tags: new[] { "non-critical", "cache" });

// Add HTTP clients with circuit breakers
builder.Services.AddHttpClient("pricing-service", client =>
{
    client.BaseAddress = new Uri("https://pricing-service");
    client.Timeout = TimeSpan.FromSeconds(3);
})
.AddTransientHttpErrorPolicy(policy =>
    policy.CircuitBreakerAsync(
        handledEventsAllowedBeforeBreaking: 3,
        durationOfBreak: TimeSpan.FromSeconds(30)));

// Add health aggregator
builder.Services.AddScoped<IHealthAggregator, HealthAggregator>();
builder.Services.AddMemoryCache();

var app = builder.Build();

// Map aggregated health endpoint
app.MapGet("/health/aggregated", async (IHealthAggregator aggregator, CancellationToken ct) =>
{
    var report = await aggregator.GetAggregatedHealthAsync(ct);

    var statusCode = report.Status switch
    {
        "healthy" => StatusCodes.Status200OK,
        "degraded" => StatusCodes.Status200OK,
        "unhealthy" => StatusCodes.Status503ServiceUnavailable,
        _ => StatusCodes.Status500InternalServerError
    };

    return Results.Json(report, statusCode: statusCode);
});

app.Run();
```

