#### Phase 3: Monitoring and Alerting

**Step 5: Configure Prometheus Metrics**

```csharp
// HealthMetricsCollector.cs
using Prometheus;

public class HealthMetricsCollector
{
    private static readonly Gauge HealthCheckStatus = Metrics.CreateGauge(
        "health_check_status",
        "Aggregated health check status (1=Healthy, 0.5=Degraded, 0=Unhealthy)",
        new GaugeConfiguration
        {
            LabelNames = new[] { "service", "status" }
        });

    private static readonly Counter HealthCheckTotal = Metrics.CreateCounter(
        "health_check_total",
        "Total number of health checks executed",
        new CounterConfiguration
        {
            LabelNames = new[] { "service", "status" }
        });

    private static readonly Histogram HealthCheckDuration = Metrics.CreateHistogram(
        "health_check_duration_seconds",
        "Health check execution duration",
        new HistogramConfiguration
        {
            LabelNames = new[] { "service", "check_name" },
            Buckets = Histogram.LinearBuckets(0.01, 0.01, 20) // 10ms to 200ms in 10ms increments
        });

    private static readonly Gauge DependencyHealth = Metrics.CreateGauge(
        "dependency_health_status",
        "Individual dependency health status",
        new GaugeConfiguration
        {
            LabelNames = new[] { "service", "dependency", "critical" }
        });

    public void RecordHealthCheck(AggregatedHealthReport report)
    {
        var serviceName = report.ServiceId;

        // Record overall health status
        var statusValue = report.Status switch
        {
            "healthy" => 1.0,
            "degraded" => 0.5,
            "unhealthy" => 0.0,
            _ => 0.0
        };

        HealthCheckStatus.WithLabels(serviceName, report.Status).Set(statusValue);
        HealthCheckTotal.WithLabels(serviceName, report.Status).Inc();
        HealthCheckDuration.WithLabels(serviceName, "aggregated").Observe(report.Duration / 1000.0);

        // Record per-dependency health
        foreach (var check in report.Checks)
        {
            var depStatusValue = check.Value.Status switch
            {
                "healthy" => 1.0,
                "degraded" => 0.5,
                "unhealthy" => 0.0,
                _ => 0.0
            };

            DependencyHealth
                .WithLabels(serviceName, check.Key, check.Value.Critical.ToString().ToLower())
                .Set(depStatusValue);

            HealthCheckDuration
                .WithLabels(serviceName, check.Key)
                .Observe(check.Value.Duration / 1000.0);
        }
    }
}
```

