**Step 7: Configure AlertManager Rules**

```yaml
# alertmanager-rules.yml
groups:

  - name: health_check_aggregation
    interval: 30s
    rules:
      - alert: ServiceUnhealthy
        expr: health_check_status{status="unhealthy"} == 0
        for: 2m
        labels:
          severity: critical
          team: platform-engineering
        annotations:
          summary: "Service {{ $labels.service }} reporting unhealthy status"
          description: "Service {{ $labels.service }} has been unhealthy for 2 minutes. Check aggregated health endpoint for dependency details."

      - alert: ServiceDegraded
        expr: health_check_status{status="degraded"} == 0.5
        for: 10m
        labels:
          severity: warning
          team: platform-engineering
        annotations:
          summary: "Service {{ $labels.service }} reporting degraded status"
          description: "Service {{ $labels.service }} has been degraded for 10 minutes due to non-critical dependency failure."

      - alert: CriticalDependencyDown
        expr: dependency_health_status{critical="true"} == 0
        for: 1m
        labels:
          severity: critical
          team: platform-engineering
        annotations:
          summary: "Critical dependency {{ $labels.dependency }} unhealthy"
          description: "Service {{ $labels.service }} reports critical dependency {{ $labels.dependency }} is unhealthy."

      - alert: HealthCheckSlow
        expr: histogram_quantile(0.95, rate(health_check_duration_seconds_bucket[5m])) > 3
        for: 5m
        labels:
          severity: warning
          team: performance
        annotations:
          summary: "Health check aggregation slow for {{ $labels.service }}"
          description: "P95 health check duration for {{ $labels.service }} exceeds 3 seconds. May cause Kubernetes probe timeouts."
```

