### Example 1: Claims Adjudication Platform Health Aggregation

**Business Context**

Gainwell's Claims Adjudication Platform processes 500,000+ claims daily across 47 interconnected microservices spanning claims intake, eligibility verification, pricing, prior authorization, payment processing, and audit logging. The platform serves 23 state Medicaid agencies with 99.5% uptime SLA and zero tolerance for claim processing failures that could delay healthcare provider payments.


**Solution Architecture**

Implemented three-tier health check aggregation:

**Tier 1: API Gateway Aggregated Health**
```text
Azure Application Gateway
    ↓ GET /health/aggregated
Claims API Gateway
    ↓ Aggregates health from 8 backend services
    ├─ Claims Intake Service
    ├─ Eligibility Service
    ├─ Pricing Service (CRITICAL)
    ├─ Prior Authorization Service
    ├─ Payment Service (CRITICAL)
    ├─ Audit Service
    ├─ Notification Service
    └─ Reporting Service
```

**Tier 2: Composite Service Aggregated Health**
```text
Pricing Service
    ↓ GET /health/aggregated
    ├─ Self Health Check (local)
    ├─ SQL Database (CRITICAL)
    │   ├─ Connection pool: 45 / 100 (45%)
    │   └─ Query time P95: 230ms
    ├─ Pricing Rules API (CRITICAL)
    │   ├─ Response time: 89ms
    │   └─ Circuit breaker: CLOSED
    └─ Redis Cache (non-critical)
        ├─ Fallback: Database
        └─ Status: Connection timeout
```

**Tier 3: Data Layer Aggregated Health**
```text
SQL Database Health Check
    ├─ Connection pool availability
    ├─ Query response time
    ├─ Disk space
    └─ Transaction log size
```

**Implementation: Claims API Gateway Aggregation**

```csharp
// ClaimsGatewayHealthAggregator.cs
public class ClaimsGatewayHealthAggregator : IHealthAggregator
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IMemoryCache _cache;
    private readonly ILogger<ClaimsGatewayHealthAggregator> _logger;

    // Backend service configuration
    private readonly Dictionary<string, ServiceConfig> _backendServices = new()
    {
        ["claims-intake"] = new ServiceConfig
        {
            Url = "https://claims-intake-service/health/aggregated",
            Critical = false,
            Timeout = TimeSpan.FromSeconds(3)
        },
        ["eligibility"] = new ServiceConfig
        {
            Url = "https://eligibility-service/health/aggregated",
            Critical = true,
            Timeout = TimeSpan.FromSeconds(3)
        },
        ["pricing"] = new ServiceConfig
        {
            Url = "https://pricing-service/health/aggregated",
            Critical = true,
            Timeout = TimeSpan.FromSeconds(3)
        },
        ["payment"] = new ServiceConfig
        {
            Url = "https://payment-service/health/aggregated",
            Critical = true,
            Timeout = TimeSpan.FromSeconds(3)
        }
    };

    public async Task<AggregatedHealthReport> GetAggregatedHealthAsync(
        CancellationToken cancellationToken = default)
    {
        var cacheKey = "claims-gateway-health";

        // Check cache (10 second TTL)
        if (_cache.TryGetValue(cacheKey, out AggregatedHealthReport cachedReport))
        {
            return cachedReport;
        }

        var stopwatch = Stopwatch.StartNew();

        // Check all backend services in parallel
        var healthCheckTasks = _backendServices
            .Select(kvp => CheckBackendServiceHealthAsync(kvp.Key, kvp.Value, cancellationToken))
            .ToList();

        var healthChecks = await Task.WhenAll(healthCheckTasks);

        stopwatch.Stop();

        // Apply aggregation logic
        var aggregatedStatus = CalculateAggregatedStatus(healthChecks);

        var report = new AggregatedHealthReport
        {
            Status = aggregatedStatus,
            Version = "1.0.0",
            ServiceId = "claims-api-gateway",
            Timestamp = DateTimeOffset.UtcNow,
            Duration = stopwatch.ElapsedMilliseconds,
            Checks = healthChecks.ToDictionary(h => h.ServiceName, h => h.Result),
            Summary = CalculateSummary(healthChecks)
        };

        // Cache for 10 seconds
        _cache.Set(cacheKey, report, TimeSpan.FromSeconds(10));

        _logger.LogInformation(
            "Claims Gateway aggregated health: {Status}, Duration: {Duration}ms, Healthy: {Healthy}/{Total}",
            aggregatedStatus,
            stopwatch.ElapsedMilliseconds,
            healthChecks.Count(h => h.Result.Status == "healthy"),
            healthChecks.Count);

        return report;
    }

    private async Task<BackendServiceHealth> CheckBackendServiceHealthAsync(
        string serviceName,
        ServiceConfig config,
        CancellationToken cancellationToken)
    {
        try
        {
            var httpClient = _httpClientFactory.CreateClient(serviceName);

            using var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            cts.CancelAfter(config.Timeout);

            var stopwatch = Stopwatch.StartNew();
            var response = await httpClient.GetAsync(config.Url, cts.Token);
            stopwatch.Stop();

            string status;
            if (response.IsSuccessStatusCode)
            {
                var content = await response.Content.ReadAsStringAsync(cts.Token);
                var healthData = JsonSerializer.Deserialize<JsonDocument>(content);
                status = healthData.RootElement.GetProperty("status").GetString();
            }
            else
            {
                status = "unhealthy";
            }

            return new BackendServiceHealth
            {
                ServiceName = serviceName,
                Result = new CheckResult
                {
                    Status = status,
                    Critical = config.Critical,
                    Duration = stopwatch.ElapsedMilliseconds,
                    Details = new Dictionary<string, object>
                    {
                        ["endpoint"] = config.Url,
                        ["httpStatus"] = (int)response.StatusCode
                    }
                }
            };
        }
        catch (TaskCanceledException)
        {
            _logger.LogWarning("Health check timeout for {ServiceName} after {Timeout}ms",
                serviceName, config.Timeout.TotalMilliseconds);

            return new BackendServiceHealth
            {
                ServiceName = serviceName,
                Result = new CheckResult
                {
                    Status = "unhealthy",
                    Critical = config.Critical,
                    Duration = (long)config.Timeout.TotalMilliseconds,
                    Error = $"Health check timeout after {config.Timeout.TotalSeconds}s"
                }
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Health check failed for {ServiceName}", serviceName);

            return new BackendServiceHealth
            {
                ServiceName = serviceName,
                Result = new CheckResult
                {
                    Status = "unhealthy",
                    Critical = config.Critical,
                    Duration = 0,
                    Error = ex.Message
                }
            };
        }
    }

    private string CalculateAggregatedStatus(IEnumerable<BackendServiceHealth> healthChecks)
    {
        // If any critical service is unhealthy, gateway is unhealthy
        if (healthChecks.Any(h => h.Result.Critical && h.Result.Status == "unhealthy"))
        {
            return "unhealthy";
        }

        // If any non-critical service is unhealthy, gateway is degraded
        if (healthChecks.Any(h => !h.Result.Critical && h.Result.Status == "unhealthy"))
        {
            return "degraded";
        }

        // If all critical services are healthy, gateway is healthy
        return "healthy";
    }
}

public class ServiceConfig
{
    public string Url { get; set; }
    public bool Critical { get; set; }
    public TimeSpan Timeout { get; set; }
}

public class BackendServiceHealth
{
    public string ServiceName { get; set; }
    public CheckResult Result { get; set; }
}
```

**Kubernetes Configuration**

