### Example 2: Member Portal API Gateway with Graceful Degradation

**Business Context**

the enterprise platform Member Portal serves 5 million active members across 23 backend microservices including authentication, member profile, benefits information, claims history, documents, secure messaging, appointment scheduling, and health plan selection. The portal handles 20 million sessions monthly with peak load of 15,000 concurrent users during open enrollment periods.

Prior to health check aggregation, the portal experienced a 15-minute degraded user experience when the Provider Directory Service's Elasticsearch cluster went down for unplanned maintenance. The API Gateway continued routing traffic to all backend services because each reported "healthy" individually, even though the Provider Directory could not fulfill provider search requests. This resulted in 15,000 failed user requests and 342 support tickets before operations manually removed the failing service from the load balancer.

**Solution Architecture**

Implemented intelligent health aggregation with graceful degradation support:

```text
Azure Application Gateway
    ↓
Member Portal API Gateway
    ↓ Aggregates health with degradation support
    ├─ Authentication Service (CRITICAL)
    ├─ Member Profile Service (CRITICAL)
    ├─ Benefits Service (CRITICAL)
    ├─ Claims History Service (CRITICAL)
    ├─ Provider Directory Service (non-critical, fallback: static directory)
    ├─ Secure Messaging Service (non-critical, fallback: offline mode)
    ├─ Documents Service (non-critical, fallback: "unavailable" message)
    └─ Appointment Scheduling (non-critical, fallback: phone number displayed)
```

**Dependency Categorization**

```yaml
# member-portal-dependencies.yml
dependencies:
  # Critical dependencies: Portal cannot function without these
  authentication-service:
    critical: true
    reason: "Users cannot log in without authentication"
    fallback: none

  member-profile-service:
    critical: true
    reason: "Cannot display member information or verify identity"
    fallback: none

  benefits-service:
    critical: true
    reason: "Core member benefit information required for all workflows"
    fallback: none

  claims-history-service:
    critical: true
    reason: "Claims viewing is primary member use case"
    fallback: none

  # Non-critical dependencies: Portal can function in degraded mode
  provider-directory-service:
    critical: false
    reason: "Provider search is optional feature"
    fallback: "Static provider directory with 'Search temporarily unavailable' message"

  secure-messaging-service:
    critical: false
    reason: "Members can use alternative contact methods"
    fallback: "Display phone number and mailing address for member services"

  documents-service:
    critical: false
    reason: "Document viewing is secondary feature"
    fallback: "Display 'Documents temporarily unavailable, call member services' message"

  appointment-scheduling:
    critical: false
    reason: "Members can schedule via phone"
    fallback: "Display provider phone numbers for scheduling"
```

**Implementation: Graceful Degradation Logic**

```csharp
// MemberPortalHealthAggregator.cs
public class MemberPortalHealthAggregator : IHealthAggregator
{
    public async Task<AggregatedHealthReport> GetAggregatedHealthAsync(
        CancellationToken cancellationToken = default)
    {
        var healthChecks = await CheckAllDependenciesAsync(cancellationToken);

        // Identify failing dependencies and activate fallbacks
        var failingDependencies = healthChecks
            .Where(h => h.Result.Status == "unhealthy")
            .ToList();

        if (failingDependencies.Any())
        {
            _logger.LogWarning(
                "Member Portal has {Count} failing dependencies: {Dependencies}",
                failingDependencies.Count,
                string.Join(", ", failingDependencies.Select(d => d.ServiceName)));

            // Activate fallback mechanisms
            foreach (var failing in failingDependencies)
            {
                await ActivateFallbackAsync(failing.ServiceName);
            }
        }

        // Calculate aggregated status with degradation support
        var status = CalculateStatusWithDegradation(healthChecks);

        var report = new AggregatedHealthReport
        {
            Status = status,
            ServiceId = "member-portal-gateway",
            Checks = healthChecks.ToDictionary(h => h.ServiceName, h => h.Result),
            Degradation = BuildDegradationInfo(failingDependencies)
        };

        return report;
    }

    private string CalculateStatusWithDegradation(IEnumerable<BackendServiceHealth> healthChecks)
    {
        var criticalUnhealthy = healthChecks
            .Where(h => h.Result.Critical && h.Result.Status == "unhealthy")
            .ToList();

        if (criticalUnhealthy.Any())
        {
            // Critical dependency down - portal unusable
            return "unhealthy";
        }

        var nonCriticalUnhealthy = healthChecks
            .Where(h => !h.Result.Critical && h.Result.Status == "unhealthy")
            .ToList();

        if (nonCriticalUnhealthy.Any())
        {
            // Non-critical dependencies down - portal degraded but functional
            return "degraded";
        }

        return "healthy";
    }

    private DegradationInfo BuildDegradationInfo(IEnumerable<BackendServiceHealth> failingDependencies)
    {
        var degradationDetails = failingDependencies
            .Where(d => !d.Result.Critical) // Only non-critical failures cause degradation
            .Select(d => new DegradationDetail
            {
                Service = d.ServiceName,
                ImpactedFeatures = GetImpactedFeatures(d.ServiceName),
                FallbackActive = true,
                FallbackDescription = GetFallbackDescription(d.ServiceName),
                UserMessage = GetUserFacingMessage(d.ServiceName)
            })
            .ToList();

        return new DegradationInfo
        {
            IsActive = degradationDetails.Any(),
            DegradedFeatures = degradationDetails,
            MemberExperience = "Core functionality available, some features temporarily unavailable"
        };
    }

    private string[] GetImpactedFeatures(string serviceName)
    {
        return serviceName switch
        {
            "provider-directory-service" => new[] { "Provider Search", "Provider Details" },
            "secure-messaging-service" => new[] { "Send Message to Care Team", "Message History" },
            "documents-service" => new[] { "View ID Card", "Download EOBs", "Document Library" },
            "appointment-scheduling" => new[] { "Schedule Appointment", "View Appointments" },
            _ => Array.Empty<string>()
        };
    }

    private string GetFallbackDescription(string serviceName)
    {
        return serviceName switch
        {
            "provider-directory-service" =>
                "Serving static provider directory, search functionality disabled",
            "secure-messaging-service" =>
                "Displaying alternative contact methods (phone, email)",
            "documents-service" =>
                "Showing member services phone number for document requests",
            "appointment-scheduling" =>
                "Displaying provider phone numbers for direct scheduling",
            _ => "Service temporarily unavailable"
        };
    }

    private string GetUserFacingMessage(string serviceName)
    {
        return serviceName switch
        {
            "provider-directory-service" =>
                "Provider search is temporarily unavailable. Please call Member Services at 1-800-XXX-XXXX for provider information.",
            "secure-messaging-service" =>
                "Secure messaging is temporarily unavailable. Please call Member Services at 1-800-XXX-XXXX or email support@example.com.",
            "documents-service" =>
                "Document viewing is temporarily unavailable. Please call Member Services at 1-800-XXX-XXXX to request documents.",
            "appointment-scheduling" =>
                "Online appointment scheduling is temporarily unavailable. Please call your provider directly to schedule.",
            _ => "This feature is temporarily unavailable. Please try again later."
        };
    }
}

public class DegradationInfo
{
    public bool IsActive { get; set; }
    public List<DegradationDetail> DegradedFeatures { get; set; }
    public string MemberExperience { get; set; }
}

public class DegradationDetail
{
    public string Service { get; set; }
    public string[] ImpactedFeatures { get; set; }
    public bool FallbackActive { get; set; }
    public string FallbackDescription { get; set; }
    public string UserMessage { get; set; }
}
```

