### Example 3: Payment Service Zero-Downtime Deployment with Dependency Validation

**Business Context**


Prior to implementing health check aggregation with deployment validation, 3 failed deployments occurred in 6 months where new service versions passed basic health checks but could not connect to required external APIs, resulting in 12 hours of emergency rollback time and significant business impact.

**Solution: Deployment Health Validation**

```yaml
# payment-service-deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: payment-service
  namespace: payment-platform
spec:
  replicas: 5
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxSurge: 1        # Deploy 1 new pod at a time
      maxUnavailable: 0  # Keep all old pods running until new pods ready

  selector:
    matchLabels:
      app: payment-service

  template:
    metadata:
      labels:
        app: payment-service
    spec:
      containers:
      - name: payment-service
        image: gainwell/payment-service:3.5.0

        # Startup probe: Validate new version can connect to ALL dependencies
        startupProbe:
          httpGet:
            path: /health/aggregated  # Aggregated health with dependency validation
            port: 8080
          initialDelaySeconds: 10
          periodSeconds: 10
          timeoutSeconds: 8
          failureThreshold: 30  # Allow 5 minutes for database migration and dependency validation

        # Readiness probe: Continue validating dependencies before accepting traffic
        readinessProbe:
          httpGet:
            path: /health/aggregated
            port: 8080
          initialDelaySeconds: 5
          periodSeconds: 5
          timeoutSeconds: 8
          failureThreshold: 2

        # Liveness probe: Check service process health (not dependencies)
        livenessProbe:
          httpGet:
            path: /health/live
            port: 8080
          initialDelaySeconds: 60
          periodSeconds: 10
          timeoutSeconds: 5
          failureThreshold: 3
```

**Aggregated Health Check with Deployment Validation**

```csharp
// PaymentServiceHealthAggregator.cs
public class PaymentServiceHealthAggregator : IHealthAggregator
{
    private readonly IConfiguration _configuration;
    private readonly ILogger<PaymentServiceHealthAggregator> _logger;

    public async Task<AggregatedHealthReport> GetAggregatedHealthAsync(
        CancellationToken cancellationToken = default)
    {
        var healthChecks = new List<NamedHealthCheck>();

        // 1. Check local service health
        healthChecks.Add(await CheckLocalHealthAsync());

        // 2. Check database connectivity and migration status
        healthChecks.Add(await CheckDatabaseAsync(cancellationToken));

        // 3. Check payment gateway connectivity
        healthChecks.Add(await CheckPaymentGatewayAsync(cancellationToken));

        // 4. Check bank ACH system connectivity
        healthChecks.Add(await CheckBankACHSystemAsync(cancellationToken));

        // 5. Check fraud detection API connectivity
        healthChecks.Add(await CheckFraudDetectionAPIAsync(cancellationToken));

        // 6. Validate configuration and credentials
        healthChecks.Add(await CheckConfigurationAsync());

        // Apply aggregation logic
        var status = CalculateAggregatedStatus(healthChecks);

        var report = new AggregatedHealthReport
        {
            Status = status,
            ServiceId = "payment-service",
            Version = Assembly.GetExecutingAssembly().GetName().Version.ToString(),
            Timestamp = DateTimeOffset.UtcNow,
            Checks = healthChecks.ToDictionary(h => h.Name, h => h.Result),
            DeploymentValidation = BuildDeploymentValidation(healthChecks, status)
        };

        // Log deployment validation result
        if (status == "healthy")
        {
            _logger.LogInformation(
                "Payment Service ready for production traffic - all dependencies validated");
        }
        else
        {
            _logger.LogError(
                "Payment Service NOT ready for production traffic - {FailedChecks} failed",
                healthChecks.Count(h => h.Result.Status != "healthy"));
        }

        return report;
    }

    private async Task<NamedHealthCheck> CheckPaymentGatewayAsync(CancellationToken cancellationToken)
    {
        try
        {
            var gatewayUrl = _configuration["PaymentGateway:Url"];
            var apiKey = _configuration["PaymentGateway:ApiKey"];

            if (string.IsNullOrEmpty(gatewayUrl) || string.IsNullOrEmpty(apiKey))
            {
                return new NamedHealthCheck
                {
                    Name = "payment-gateway",
                    Result = new CheckResult
                    {
                        Status = "unhealthy",
                        Critical = true,
                        Error = "Payment gateway configuration missing"
                    }
                };
            }

            // Make test API call to payment gateway
            using var client = new HttpClient();
            client.DefaultRequestHeaders.Add("Authorization", $"Bearer {apiKey}");
            client.Timeout = TimeSpan.FromSeconds(5);

            var response = await client.GetAsync($"{gatewayUrl}/health", cancellationToken);

            if (response.IsSuccessStatusCode)
            {
                return new NamedHealthCheck
                {
                    Name = "payment-gateway",
                    Result = new CheckResult
                    {
                        Status = "healthy",
                        Critical = true,
                        Details = new Dictionary<string, object>
                        {
                            ["endpoint"] = gatewayUrl,
                            ["authenticated"] = true
                        }
                    }
                };
            }

            return new NamedHealthCheck
            {
                Name = "payment-gateway",
                Result = new CheckResult
                {
                    Status = "unhealthy",
                    Critical = true,
                    Error = $"Payment gateway returned {response.StatusCode}"
                }
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Payment gateway health check failed");
            return new NamedHealthCheck
            {
                Name = "payment-gateway",
                Result = new CheckResult
                {
                    Status = "unhealthy",
                    Critical = true,
                    Error = ex.Message
                }
            };
        }
    }

    private DeploymentValidation BuildDeploymentValidation(
        List<NamedHealthCheck> healthChecks,
        string status)
    {
        var criticalChecks = healthChecks.Where(h => h.Result.Critical).ToList();
        var failedCritical = criticalChecks.Where(h => h.Result.Status != "healthy").ToList();

        return new DeploymentValidation
        {
            ReadyForTraffic = status == "healthy",
            ValidatedAt = DateTimeOffset.UtcNow,
            CriticalDependenciesValidated = criticalChecks.Count,
            CriticalDependenciesPassed = criticalChecks.Count - failedCritical.Count,
            FailedValidations = failedCritical.Select(f => new FailedValidation
            {
                Dependency = f.Name,
                Reason = f.Result.Error ?? "Health check failed",
                RecommendedAction = GetRecommendedAction(f.Name)
            }).ToList(),
            DeploymentAdvice = status == "healthy"
                ? "Service validated and ready for production traffic"
                : $"DO NOT DEPLOY: {failedCritical.Count} critical dependencies failed validation"
        };
    }

    private string GetRecommendedAction(string dependencyName)
    {
        return dependencyName switch
        {
            "payment-gateway" =>
                "Verify payment gateway API key configured correctly in Azure Key Vault",
            "bank-ach-system" =>
                "Verify bank ACH credentials and firewall rules allow connectivity",
            "fraud-detection-api" =>
                "Verify fraud detection API subscription active and credentials valid",
            "database" =>
                "Verify database migration completed successfully and connection string correct",
            _ => "Check service configuration and dependency availability"
        };
    }
}

public class DeploymentValidation
{
    public bool ReadyForTraffic { get; set; }
    public DateTimeOffset ValidatedAt { get; set; }
    public int CriticalDependenciesValidated { get; set; }
    public int CriticalDependenciesPassed { get; set; }
    public List<FailedValidation> FailedValidations { get; set; }
    public string DeploymentAdvice { get; set; }
}

public class FailedValidation
{
    public string Dependency { get; set; }
    public string Reason { get; set; }
    public string RecommendedAction { get; set; }
}
